     1→import { readFileSync, readdirSync, statSync } from 'fs';
     2→import { join } from 'path';
     3→import { 
     4→  BundleSchema, 
     5→  Bundle, 
     6→  extractBundleSummary, 
     7→  validateBundleStructure,
     8→  getPatientFromBundle,
     9→  extractPatientSummary,
    10→  type Patient
    11→} from '../schema';
    12→
    13→/**
    14→ * FHIR Bundle Loader
    15→ * 
    16→ * Loads and validates FHIR bundles from JSON files.
    17→ * Provides utility functions for reading, validating, and analyzing the healthcare data.
    18→ */
    19→
    20→export interface LoadResult {
    21→  success: boolean;
    22→  bundle?: Bundle;
    23→  patient?: Patient;
    24→  errors: string[];
    25→  warnings: string[];
    26→  stats: {
    27→    fileName: string;
    28→    fileSize: number;
    29→    fileSizeMB: number;
    30→    entryCount: number;
    31→    resourceTypeCounts: Record<string, number>;
    32→  };
    33→}
    34→
    35→export interface LoadOptions {
    36→  validate?: boolean;
    37→  includePatientSummary?: boolean;
    38→  strict?: boolean;
    39→}
    40→
    41→/**
    42→ * Load a single FHIR bundle from a JSON file
    43→ */
    44→export function loadFhirBundle(filePath: string, options: LoadOptions = {}): LoadResult {
    45→  const {
    46→    validate = true,
    47→    includePatientSummary = true,
    48→    strict = false
    49→  } = options;
    50→
    51→  const fileName = filePath.split('/').pop() || 'unknown';
    52→  const errors: string[] = [];
    53→  const warnings: string[] = [];
    54→  
    55→  try {
    56→    // Read and parse the JSON file
    57→    const fileStats = statSync(filePath);
    58→    const fileSize = fileStats.size;
    59→    const fileSizeMB = Math.round(fileSize / (1024 * 1024) * 10) / 10;
    60→    
    61→    const jsonContent = readFileSync(filePath, 'utf-8');
    62→    const rawData = JSON.parse(jsonContent);
    63→    
    64→    // Validate with Zod schema
    65→    let bundle: Bundle;
    66→    try {
    67→      bundle = BundleSchema.parse(rawData);
    68→    } catch (zodError: any) {
    69→      if (strict) {
    70→        return {
    71→          success: false,
    72→          errors: [`Schema validation failed: ${zodError.message}`],
    73→          warnings,
    74→          stats: {
    75→            fileName,
    76→            fileSize,
    77→            fileSizeMB,
    78→            entryCount: 0,
    79→            resourceTypeCounts: {},
    80→          }
    81→        };
    82→      } else {
    83→        // In non-strict mode, try to work with the data anyway
    84→        warnings.push(`Schema validation failed, proceeding anyway: ${zodError.message}`);
    85→        bundle = rawData as Bundle;
    86→      }
    87→    }
    88→    
    89→    // Extract statistics
    90→    const bundleSummary = extractBundleSummary(bundle);
    91→    const entryCount = bundle.entry?.length || 0;
    92→    
    93→    // Validate bundle structure
    94→    if (validate) {
    95→      const structureValidation = validateBundleStructure(bundle);
    96→      if (!structureValidation.isValid) {
    97→        errors.push(...structureValidation.errors);
    98→      }
    99→    }
   100→    
   101→    // Extract patient information
   102→    let patient: Patient | undefined;
   103→    if (includePatientSummary) {
   104→      patient = getPatientFromBundle(bundle);
   105→      if (!patient) {
   106→        errors.push('No patient resource found in bundle');
   107→      }
   108→    }
   109→    
   110→    return {
   111→      success: errors.length === 0,
   112→      bundle,
   113→      patient,
   114→      errors,
   115→      warnings,
   116→      stats: {
   117→        fileName,
   118→        fileSize,
   119→        fileSizeMB,
   120→        entryCount,
   121→        resourceTypeCounts: bundleSummary.resourceTypeCounts,
   122→      }
   123→    };
   124→    
   125→  } catch (error: any) {
   126→    return {
   127→      success: false,
   128→      errors: [`Failed to load file: ${error.message}`],
   129→      warnings,
   130→      stats: {
   131→        fileName,
   132→        fileSize: 0,
   133→        fileSizeMB: 0,
   134→        entryCount: 0,
   135→        resourceTypeCounts: {},
   136→      }
   137→    };
   138→  }
   139→}
   140→
   141→/**
   142→ * Load multiple FHIR bundles from a directory
   143→ */
   144→export function loadFhirBundles(
   145→  directoryPath: string, 
   146→  options: LoadOptions & { limit?: number } = {}
   147→): LoadResult[] {
   148→  const { limit, ...loadOptions } = options;
   149→  
   150→  try {
   151→    const files = readdirSync(directoryPath)
   152→      .filter(file => file.endsWith('.json'))
   153→      .slice(0, limit);
   154→    
   155→    return files.map(fileName => {
   156→      const filePath = join(directoryPath, fileName);
   157→      return loadFhirBundle(filePath, loadOptions);
   158→    });
   159→    
   160→  } catch (error: any) {
   161→    return [{
   162→      success: false,
   163→      errors: [`Failed to read directory: ${error.message}`],
   164→      warnings: [],
   165→      stats: {
   166→        fileName: 'directory',
   167→        fileSize: 0,
   168→        fileSizeMB: 0,
   169→        entryCount: 0,
   170→        resourceTypeCounts: {},
   171→      }
   172→    }];
   173→  }
   174→}
   175→
   176→/**
   177→ * Analyze a directory of FHIR bundles and return aggregate statistics
   178→ */
   179→export function analyzeFhirDirectory(directoryPath: string, sampleSize: number = 50) {
   180→  const results = loadFhirBundles(directoryPath, { limit: sampleSize });
   181→  
   182→  const successfulLoads = results.filter(r => r.success);
   183→  const failedLoads = results.filter(r => !r.success);
   184→  
   185→  const totalEntries = successfulLoads.reduce((sum, r) => sum + r.stats.entryCount, 0);
   186→  const totalSizeMB = successfulLoads.reduce((sum, r) => sum + r.stats.fileSizeMB, 0);
   187→  
   188→  const aggregatedResourceCounts: Record<string, number> = {};
   189→  successfulLoads.forEach(result => {
   190→    Object.entries(result.stats.resourceTypeCounts).forEach(([type, count]) => {
   191→      aggregatedResourceCounts[type] = (aggregatedResourceCounts[type] || 0) + count;
   192→    });
   193→  });
   194→  
   195→  const fileSizes = successfulLoads.map(r => r.stats.fileSizeMB);
   196→  const entryCounts = successfulLoads.map(r => r.stats.entryCount);
   197→  
   198→  return {
   199→    summary: {
   200→      totalFiles: results.length,
   201→      successfulLoads: successfulLoads.length,
   202→      failedLoads: failedLoads.length,
   203→      totalEntries,
   204→      totalSizeMB,
   205→      avgEntriesPerFile: totalEntries / successfulLoads.length,
   206→      avgSizeMBPerFile: totalSizeMB / successfulLoads.length,
   207→    },
   208→    
   209→    distributionStats: {
   210→      fileSizes: {
   211→        min: Math.min(...fileSizes),
   212→        max: Math.max(...fileSizes),
   213→        median: fileSizes.sort()[Math.floor(fileSizes.length / 2)],
   214→      },
   215→      entryCounts: {
   216→        min: Math.min(...entryCounts),
   217→        max: Math.max(...entryCounts),
   218→        median: entryCounts.sort()[Math.floor(entryCounts.length / 2)],
   219→      },
   220→    },
   221→    
   222→    resourceTypeDistribution: Object.entries(aggregatedResourceCounts)
   223→      .sort(([, a], [, b]) => b - a)
   224→      .reduce((acc, [type, count]) => {
   225→        acc[type] = {
   226→          count,
   227→          percentage: (count / totalEntries) * 100,
   228→        };
   229→        return acc;
   230→      }, {} as Record<string, { count: number; percentage: number }>),
   231→    
   232→    errors: failedLoads.flatMap(r => r.errors),
   233→    warnings: results.flatMap(r => r.warnings),
   234→    
   235→    patientSummaries: successfulLoads
   236→      .map(r => r.patient ? extractPatientSummary(r.patient) : null)
   237→      .filter(Boolean),
   238→  };
   239→}
   240→
   241→/**
   242→ * Utility function to get sample data for testing
   243→ */
   244→export function getSampleBundles(directoryPath: string, count: number = 3) {
   245→  const files = readdirSync(directoryPath)
   246→    .filter(file => file.endsWith('.json'));
   247→  
   248→  // Get small, medium, and large files
   249→  const fileStats = files.map(file => ({
   250→    name: file,
   251→    size: statSync(join(directoryPath, file)).size,
   252→  })).sort((a, b) => a.size - b.size);
   253→  
   254→  const sampleFiles = [
   255→    fileStats[0], // smallest
   256→    fileStats[Math.floor(fileStats.length / 2)], // median
   257→    fileStats[fileStats.length - 1], // largest
   258→  ].slice(0, count);
   259→  
   260→  return sampleFiles.map(file => 
   261→    loadFhirBundle(join(directoryPath, file.name))
   262→  );
   263→}

