import { z } from 'zod';
import { 
  BaseResourceSchema, 
  CodeableConceptSchema, 
  ReferenceSchema, 
  PeriodSchema, 
  IdentifierSchema,
  QuantitySchema
} from './common';

/**
 * Encounter Resource Schema
 * 
 * Encounters represent clinical visits, interactions, or episodes of care.
 * They provide the context for many other clinical resources.
 * 
 * Key observations from the dataset:
 * - Status is typically "finished" for completed encounters
 * - Class is usually "AMB" (ambulatory)
 * - Types include "Well child visit", "General examination", etc.
 * - All encounters reference a patient (subject)
 * - Periods show start/end times of the encounter
 * - Participants include healthcare providers
 * - Service providers are typically organizations
 * - Locations indicate where the encounter took place
 * 
 * OUTLIERS DISCOVERED:
 * - Very long encounters (>24 hrs) are clinically appropriate (hospice, rehab)
 * - Some encounters overlap for the same patient (potential data quality issue)
 * - Encounters can occur at the exact same time (millisecond precision needed)
 * - Peak encounter times are 9:00 AM and 7:00 AM (business hours pattern)
 * - Average encounter duration is ~265 minutes, median is ~33 minutes
 * - All encounters have exactly 1 participant on average
 */

// Encounter status values
const EncounterStatusSchema = z.enum([
  'planned',
  'arrived',
  'triaged',
  'in-progress',
  'onleave',
  'finished',
  'cancelled',
  'entered-in-error',
  'unknown'
]);

// Encounter class (ambulatory, emergency, inpatient, etc.)
const EncounterClassSchema = z.object({
  system: z.string(),
  code: z.string(),
  display: z.string().optional(),
});

// Participant in the encounter
const ParticipantSchema = z.object({
  type: z.array(CodeableConceptSchema).optional(),
  period: PeriodSchema.optional(),
  individual: ReferenceSchema.optional(),
});

// Diagnosis associated with the encounter
const DiagnosisSchema = z.object({
  condition: ReferenceSchema,
  use: CodeableConceptSchema.optional(),
  rank: z.number().optional(),
});

// Hospitalization details
const HospitalizationSchema = z.object({
  preAdmissionIdentifier: IdentifierSchema.optional(),
  origin: ReferenceSchema.optional(),
  admitSource: CodeableConceptSchema.optional(),
  reAdmission: CodeableConceptSchema.optional(),
  dietPreference: z.array(CodeableConceptSchema).optional(),
  specialCourtesy: z.array(CodeableConceptSchema).optional(),
  specialArrangement: z.array(CodeableConceptSchema).optional(),
  destination: ReferenceSchema.optional(),
  dischargeDisposition: CodeableConceptSchema.optional(),
});

// Location where encounter took place
const LocationSchema = z.object({
  location: ReferenceSchema,
  status: z.enum(['planned', 'active', 'reserved', 'completed']).optional(),
  physicalType: CodeableConceptSchema.optional(),
  period: PeriodSchema.optional(),
});

// Status history of the encounter
const StatusHistorySchema = z.object({
  status: EncounterStatusSchema,
  period: PeriodSchema,
});

// Class history of the encounter
const ClassHistorySchema = z.object({
  class: EncounterClassSchema,
  period: PeriodSchema,
});

/**
 * Encounter Resource
 * 
 * Represents an interaction between a patient and healthcare provider(s).
 * Provides context for observations, procedures, and other clinical activities.
 */
export const EncounterSchema = BaseResourceSchema.extend({
  resourceType: z.literal('Encounter'),

  // Business identifiers
  identifier: z.array(IdentifierSchema).optional(),

  // Current status of the encounter
  status: EncounterStatusSchema,

  // Status history
  statusHistory: z.array(StatusHistorySchema).optional(),

  // Classification of patient encounter
  class: EncounterClassSchema.optional(),

  // Class history
  classHistory: z.array(ClassHistorySchema).optional(),

  // Specific type of encounter
  type: z.array(CodeableConceptSchema).optional(),

  // Specific type of service
  serviceType: CodeableConceptSchema.optional(),

  // Indicates the urgency of the encounter
  priority: CodeableConceptSchema.optional(),

  // The patient present at the encounter
  subject: ReferenceSchema.optional(),

  // Episode(s) of care that this encounter should be recorded against
  episodeOfCare: z.array(ReferenceSchema).optional(),

  // The request this encounter satisfies
  basedOn: z.array(ReferenceSchema).optional(),

  // List of participants involved in the encounter
  participant: z.array(ParticipantSchema).optional(),

  // The appointment that scheduled this encounter
  appointment: z.array(ReferenceSchema).optional(),

  // The start and end time of the encounter
  period: PeriodSchema.optional(),

  // Quantity of time the encounter lasted
  length: QuantitySchema.optional(),

  // Coded reason the encounter takes place
  reasonCode: z.array(CodeableConceptSchema).optional(),

  // Reason the encounter takes place (reference)
  reasonReference: z.array(ReferenceSchema).optional(),

  // The list of diagnosis relevant to this encounter
  diagnosis: z.array(DiagnosisSchema).optional(),

  // The set of accounts that may be used for billing
  account: z.array(ReferenceSchema).optional(),

  // Details about the admission to a healthcare service
  hospitalization: HospitalizationSchema.optional(),

  // List of locations where the patient has been
  location: z.array(LocationSchema).optional(),

  // The organization responsible for this encounter
  serviceProvider: ReferenceSchema.optional(),

  // Another encounter this encounter is part of
  partOf: ReferenceSchema.optional(),
});

export type Encounter = z.infer<typeof EncounterSchema>;

/**
 * Utility function to extract encounter summary
 * Useful for debugging and data analysis
 */
export function extractEncounterSummary(encounter: Encounter) {
  const encounterType = encounter.type?.[0]?.text || encounter.type?.[0]?.coding?.[0]?.display || 'Unknown';
  const encounterClass = encounter.class?.display || encounter.class?.code || 'Unknown';

  return {
    id: encounter.id,
    status: encounter.status,
    class: encounterClass,
    type: encounterType,
    period: encounter.period,
    patientRef: encounter.subject?.reference,
    serviceProvider: encounter.serviceProvider?.display,
    participantCount: encounter.participant?.length || 0,
    locationCount: encounter.location?.length || 0,
  };
}

