  DateTimeSchema,
  DateSchema,
  PeriodSchema,
  IdentifierSchema
} from './common';

/**
 * Condition Resource Schema
 * 
 * Conditions represent diagnoses, problems, or other clinical conditions.
 * They are typically identified during encounters and may persist over time.
 * 
 * Key observations from the dataset:
 * - Clinical status is typically "active" or "resolved"
 * - Verification status is usually "confirmed"
 * - Categories include "encounter-diagnosis", "problem-list-item"
 * - Codes use SNOMED CT system (http://snomed.info/sct)
 * - Conditions reference the patient (subject) and encounter (context)
 * - Onset can be dateTime, age, period, range, or string
 * - Severity and stage information may be present
 * - Evidence links to supporting observations
 */

// Clinical status of the condition
const ClinicalStatusSchema = z.object({
  coding: z.array(z.object({
    system: z.literal('http://terminology.hl7.org/CodeSystem/condition-clinical'),
    code: z.enum(['active', 'recurrence', 'relapse', 'inactive', 'remission', 'resolved']),
    display: z.string().optional(),
  })),
  text: z.string().optional(),
});

// Verification status of the condition
const VerificationStatusSchema = z.object({
  coding: z.array(z.object({
    system: z.literal('http://terminology.hl7.org/CodeSystem/condition-ver-status'),
    code: z.enum(['unconfirmed', 'provisional', 'differential', 'confirmed', 'refuted', 'entered-in-error']),
    display: z.string().optional(),
  })),
  text: z.string().optional(),
});

// Evidence supporting the condition
const EvidenceSchema = z.object({
  code: z.array(CodeableConceptSchema).optional(),
  detail: z.array(ReferenceSchema).optional(),
});

// Stage of the condition
const StageSchema = z.object({
  summary: CodeableConceptSchema.optional(),
  assessment: z.array(ReferenceSchema).optional(),
  type: CodeableConceptSchema.optional(),
});

/**
 * Condition Resource
 * 
 * Represents a clinical condition, problem, diagnosis, or other event,
 * situation, issue, or clinical concept that has risen to a level of concern.
 */
export const ConditionSchema = BaseResourceSchema.extend({
  resourceType: z.literal('Condition'),

  // Business identifiers
  identifier: z.array(IdentifierSchema).optional(),

  // Clinical status of the condition
  clinicalStatus: ClinicalStatusSchema.optional(),

  // Verification status of the condition
  verificationStatus: VerificationStatusSchema.optional(),

  // Category of the condition
  category: z.array(CodeableConceptSchema).optional(),

  // Subjective severity of condition
  severity: CodeableConceptSchema.optional(),

  // Identification of the condition or diagnosis
  code: CodeableConceptSchema.optional(),

  // Anatomical location
  bodySite: z.array(CodeableConceptSchema).optional(),

  // Who has the condition
  subject: ReferenceSchema,

  // Encounter created as part of
  encounter: ReferenceSchema.optional(),

  // Estimated or actual date, date-time, or age
  onsetDateTime: DateTimeSchema.optional(),
  onsetAge: z.object({
    value: z.number(),
    unit: z.string(),
    system: z.string().optional(),
    code: z.string().optional(),
  }).optional(),
  onsetPeriod: PeriodSchema.optional(),
  onsetRange: z.object({
    low: z.object({
      value: z.number(),
      unit: z.string(),
    }).optional(),
    high: z.object({
      value: z.number(),
      unit: z.string(),
    }).optional(),
  }).optional(),
  onsetString: z.string().optional(),

  // When in resolution/remission
  abatementDateTime: DateTimeSchema.optional(),
  abatementAge: z.object({
    value: z.number(),
    unit: z.string(),
    system: z.string().optional(),
    code: z.string().optional(),
  }).optional(),
  abatementPeriod: PeriodSchema.optional(),
  abatementRange: z.object({
    low: z.object({
      value: z.number(),
      unit: z.string(),
    }).optional(),
    high: z.object({
      value: z.number(),
      unit: z.string(),
    }).optional(),
  }).optional(),
  abatementString: z.string().optional(),

  // Date record was first recorded
  recordedDate: DateTimeSchema.optional(),

  // Who recorded the condition
  recorder: ReferenceSchema.optional(),

  // Person who asserts this condition
  asserter: ReferenceSchema.optional(),

  // Stage/grade of the condition
  stage: z.array(StageSchema).optional(),

  // Supporting evidence
  evidence: z.array(EvidenceSchema).optional(),

  // Additional information about the condition
  note: z.array(z.object({
    authorReference: ReferenceSchema.optional(),
    authorString: z.string().optional(),
    time: DateTimeSchema.optional(),
    text: z.string(),
  })).optional(),
});

export type Condition = z.infer<typeof ConditionSchema>;

/**
 * Utility function to extract condition summary
 * Useful for debugging and data analysis
 */
export function extractConditionSummary(condition: Condition) {
  const conditionName = condition.code?.text || condition.code?.coding?.[0]?.display || 'Unknown condition';
  const clinicalStatus = condition.clinicalStatus?.coding?.[0]?.code || 'Unknown';
  const verificationStatus = condition.verificationStatus?.coding?.[0]?.code || 'Unknown';

  return {
    id: condition.id,
    condition: conditionName,
    clinicalStatus,
    verificationStatus,
    category: condition.category?.[0]?.coding?.[0]?.display,
    severity: condition.severity?.text || condition.severity?.coding?.[0]?.display,
    onsetDateTime: condition.onsetDateTime,
    patientRef: condition.subject?.reference,
    encounterRef: condition.encounter?.reference,
    bodysite: condition.bodySite?.[0]?.text,
  };
}

