import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';
import { 
  BundleSchema, 
  Bundle, 
  extractBundleSummary, 
  validateBundleStructure,
  getPatientFromBundle,
  extractPatientSummary,
  Patient
} from '../schemas';

/**
 * FHIR Bundle Loader
 * 
 * Loads and validates FHIR bundles from JSON files.
 * Provides utility functions for reading, validating, and analyzing the healthcare data.
 */

export interface LoadResult {
  success: boolean;
  bundle?: Bundle;
  patient?: Patient;
  errors: string[];
  warnings: string[];
  stats: {
    fileName: string;
    fileSize: number;
    fileSizeMB: number;
    entryCount: number;
    resourceTypeCounts: Record<string, number>;
  };
}

export interface LoadOptions {
  validate?: boolean;
  includePatientSummary?: boolean;
  strict?: boolean;
}

/**
 * Load a single FHIR bundle from a JSON file
 */
export function loadFhirBundle(filePath: string, options: LoadOptions = {}): LoadResult {
  const {
    validate = true,
    includePatientSummary = true,
    strict = false
  } = options;

  const fileName = filePath.split('/').pop() || 'unknown';
  const errors: string[] = [];
  const warnings: string[] = [];

  try {
    // Read and parse the JSON file
    const fileStats = statSync(filePath);
    const fileSize = fileStats.size;
    const fileSizeMB = Math.round(fileSize / (1024 * 1024) * 10) / 10;

    const jsonContent = readFileSync(filePath, 'utf-8');
    const rawData = JSON.parse(jsonContent);

    // Validate with Zod schema
    let bundle: Bundle;
    try {
      bundle = BundleSchema.parse(rawData);
    } catch (zodError: any) {
      if (strict) {
        return {
          success: false,
          errors: [`Schema validation failed: ${zodError.message}`],
          warnings,
          stats: {
            fileName,
            fileSize,
            fileSizeMB,
            entryCount: 0,
            resourceTypeCounts: {},
          }
        };
      } else {
        // In non-strict mode, try to work with the data anyway
        warnings.push(`Schema validation failed, proceeding anyway: ${zodError.message}`);
        bundle = rawData as Bundle;
      }
    }

    // Extract statistics
    const bundleSummary = extractBundleSummary(bundle);
    const entryCount = bundle.entry?.length || 0;

    // Validate bundle structure
    if (validate) {
      const structureValidation = validateBundleStructure(bundle);
      if (!structureValidation.isValid) {
        errors.push(...structureValidation.errors);
      }
    }

    // Extract patient information
    let patient: Patient | undefined;
    if (includePatientSummary) {
      patient = getPatientFromBundle(bundle);
      if (!patient) {
        errors.push('No patient resource found in bundle');
      }
    }

    return {
      success: errors.length === 0,
      bundle,
      patient,
      errors,
      warnings,
      stats: {
        fileName,
        fileSize,
        fileSizeMB,
        entryCount,
        resourceTypeCounts: bundleSummary.resourceTypeCounts,
      }
    };

  } catch (error: any) {
    return {
      success: false,
      errors: [`Failed to load file: ${error.message}`],
      warnings,
      stats: {
        fileName,
        fileSize: 0,
        fileSizeMB: 0,
        entryCount: 0,
        resourceTypeCounts: {},
      }
    };
  }
}

/**
 * Load multiple FHIR bundles from a directory
 */
export function loadFhirBundles(
  directoryPath: string, 
  options: LoadOptions & { limit?: number } = {}
): LoadResult[] {
  const { limit, ...loadOptions } = options;

  try {
    const files = readdirSync(directoryPath)
      .filter(file => file.endsWith('.json'))
      .slice(0, limit);

    return files.map(fileName => {
      const filePath = join(directoryPath, fileName);
      return loadFhirBundle(filePath, loadOptions);
    });

  } catch (error: any) {
    return [{
      success: false,
      errors: [`Failed to read directory: ${error.message}`],
      warnings: [],
      stats: {
        fileName: 'directory',
        fileSize: 0,
        fileSizeMB: 0,
        entryCount: 0,
        resourceTypeCounts: {},
      }
    }];
  }
}

/**
 * Analyze a directory of FHIR bundles and return aggregate statistics
 */
export function analyzeFhirDirectory(directoryPath: string, sampleSize: number = 50) {
  const results = loadFhirBundles(directoryPath, { limit: sampleSize });

  const successfulLoads = results.filter(r => r.success);
  const failedLoads = results.filter(r => !r.success);

  const totalEntries = successfulLoads.reduce((sum, r) => sum + r.stats.entryCount, 0);
  const totalSizeMB = successfulLoads.reduce((sum, r) => sum + r.stats.fileSizeMB, 0);

  const aggregatedResourceCounts: Record<string, number> = {};
  successfulLoads.forEach(result => {
    Object.entries(result.stats.resourceTypeCounts).forEach(([type, count]) => {
      aggregatedResourceCounts[type] = (aggregatedResourceCounts[type] || 0) + count;
    });
  });

  const fileSizes = successfulLoads.map(r => r.stats.fileSizeMB);
  const entryCounts = successfulLoads.map(r => r.stats.entryCount);

  return {
    summary: {
      totalFiles: results.length,
      successfulLoads: successfulLoads.length,
      failedLoads: failedLoads.length,
      totalEntries,
      totalSizeMB,
      avgEntriesPerFile: totalEntries / successfulLoads.length,
      avgSizeMBPerFile: totalSizeMB / successfulLoads.length,
    },

    distributionStats: {
      fileSizes: {
        min: Math.min(...fileSizes),
        max: Math.max(...fileSizes),
        median: fileSizes.sort()[Math.floor(fileSizes.length / 2)],
      },
      entryCounts: {
        min: Math.min(...entryCounts),
        max: Math.max(...entryCounts),
        median: entryCounts.sort()[Math.floor(entryCounts.length / 2)],
      },
    },

    resourceTypeDistribution: Object.entries(aggregatedResourceCounts)
      .sort(([, a], [, b]) => b - a)
      .reduce((acc, [type, count]) => {
        acc[type] = {
          count,
          percentage: (count / totalEntries) * 100,
        };
        return acc;
      }, {} as Record<string, { count: number; percentage: number }>),

    errors: failedLoads.flatMap(r => r.errors),
    warnings: results.flatMap(r => r.warnings),

    patientSummaries: successfulLoads
      .map(r => r.patient ? extractPatientSummary(r.patient) : null)
      .filter(Boolean),
  };
}

/**
 * Utility function to get sample data for testing
 */
export function getSampleBundles(directoryPath: string, count: number = 3) {
  const files = readdirSync(directoryPath)
    .filter(file => file.endsWith('.json'));

  // Get small, medium, and large files
  const fileStats = files.map(file => ({
    name: file,
    size: statSync(join(directoryPath, file)).size,
  })).sort((a, b) => a.size - b.size);

  const sampleFiles = [
    fileStats[0], // smallest
    fileStats[Math.floor(fileStats.length / 2)], // median
    fileStats[fileStats.length - 1], // largest
  ].slice(0, count);

  return sampleFiles.map(file => 
    loadFhirBundle(join(directoryPath, file.name))
  );
}

import { Bundle, Patient, Observation, Encounter, Condition } from '../schemas';
import { LoadResult } from '../loaders/fhir-loader';

/**
 * Comprehensive Data Quality Validation
 * 
 * Based on insights from the previous engineer's analysis of the healthcare dataset.
 * Implements validation checks for data quality, consistency, and clinical appropriateness.
 */

export interface ValidationResult {
  isValid: boolean;
  errors: string[];
  warnings: string[];
  qualityScore: number; // 0-100
  details: {
    patientValidation?: PatientValidationResult;
    observationValidation?: ObservationValidationResult;
    encounterValidation?: EncounterValidationResult;
    conditionValidation?: ConditionValidationResult;
    crossResourceValidation?: CrossResourceValidationResult;
  };
}

export interface PatientValidationResult {
  namePatternValid: boolean;
  identifiersComplete: boolean;
  demographicsValid: boolean;
  contactInfoValid: boolean;
  geographicConsistent: boolean;
}

export interface ObservationValidationResult {
  statusConsistent: boolean;
  valuesInRange: boolean;
  unitsValid: boolean;
  referencesValid: boolean;
  temporalConsistent: boolean;
}

export interface EncounterValidationResult {
  durationsRealistic: boolean;
  typesValid: boolean;
  temporalConsistent: boolean;
  overlapsDetected: boolean;
  participantsValid: boolean;
}

export interface ConditionValidationResult {
  statusesValid: boolean;
  onsetConsistent: boolean;
  severityAppropriate: boolean;
  evidenceLinked: boolean;
}

export interface CrossResourceValidationResult {
  referenceIntegrity: boolean;
  temporalConsistency: boolean;
  clinicalLogic: boolean;
  duplicatesDetected: boolean;
}

/**
 * Comprehensive validation of a FHIR bundle
 */
export function validateBundle(bundle: Bundle): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Extract resources for validation
  const patient = bundle.entry?.find(e => e.resource?.resourceType === 'Patient')?.resource as Patient;
  const observations = bundle.entry?.filter(e => e.resource?.resourceType === 'Observation')?.map(e => e.resource) as Observation[];
  const encounters = bundle.entry?.filter(e => e.resource?.resourceType === 'Encounter')?.map(e => e.resource) as Encounter[];
  const conditions = bundle.entry?.filter(e => e.resource?.resourceType === 'Condition')?.map(e => e.resource) as Condition[];

  // Individual resource validations
  const patientValidation = patient ? validatePatient(patient) : undefined;
  const observationValidation = observations ? validateObservations(observations) : undefined;
  const encounterValidation = encounters ? validateEncounters(encounters) : undefined;
  const conditionValidation = conditions ? validateConditions(conditions) : undefined;

  // Cross-resource validation
  const crossResourceValidation = validateCrossResource(bundle, {
    patient,
    observations: observations || [],
    encounters: encounters || [],
    conditions: conditions || []
  });

  // Collect all errors and warnings
  if (patientValidation) {
    errors.push(...patientValidation.errors);
    warnings.push(...patientValidation.warnings);
  }
  if (observationValidation) {
    errors.push(...observationValidation.errors);
    warnings.push(...observationValidation.warnings);
  }
  if (encounterValidation) {
    errors.push(...encounterValidation.errors);
    warnings.push(...encounterValidation.warnings);
  }
  if (conditionValidation) {
    errors.push(...conditionValidation.errors);
    warnings.push(...conditionValidation.warnings);
  }
  if (crossResourceValidation) {
    errors.push(...crossResourceValidation.errors);
    warnings.push(...crossResourceValidation.warnings);
  }

  // Calculate quality score
  const qualityScore = calculateQualityScore(errors, warnings, bundle);

  return {
    isValid: errors.length === 0,
    errors,
    warnings,
    qualityScore,
    details: {
      patientValidation: patientValidation?.result,
      observationValidation: observationValidation?.result,
      encounterValidation: encounterValidation?.result,
      conditionValidation: conditionValidation?.result,
      crossResourceValidation: crossResourceValidation?.result,
    }
  };
}

/**
 * Validate patient resource
 */
function validatePatient(patient: Patient) {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Name pattern validation (flexible for international names)
  const namePatternValid = validatePatientNames(patient, warnings);

  // Identifier completeness
  const identifiersComplete = validatePatientIdentifiers(patient, warnings);

  // Demographics validation
  const demographicsValid = validatePatientDemographics(patient, errors);

  // Contact information validation
  const contactInfoValid = validatePatientContact(patient, warnings);

  // Geographic consistency (all should be Massachusetts)
  const geographicConsistent = validatePatientGeography(patient, warnings);

  const result: PatientValidationResult = {
    namePatternValid,
    identifiersComplete,
    demographicsValid,
    contactInfoValid,
    geographicConsistent,
  };

  return { errors, warnings, result };
}

/**
 * Validate observation resources
 */
function validateObservations(observations: Observation[]) {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Status consistency check (should all be "final")
  const statusConsistent = observations.every(obs => obs.status === 'final');
  if (!statusConsistent) {
    warnings.push('Some observations have non-final status');
  }

  // Value range validation (accounting for scientific notation)
  const valuesInRange = validateObservationValues(observations, warnings);

  // Unit validation (handle scientific notation)
  const unitsValid = validateObservationUnits(observations, warnings);

  // Reference validation
  const referencesValid = validateObservationReferences(observations, errors);

  // Temporal consistency
  const temporalConsistent = validateObservationTemporal(observations, warnings);

  const result: ObservationValidationResult = {
    statusConsistent,
    valuesInRange,
    unitsValid,
    referencesValid,
    temporalConsistent,
  };

  return { errors, warnings, result };
}

/**
 * Validate encounter resources
 */
function validateEncounters(encounters: Encounter[]) {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Duration validation (long encounters are valid for certain types)
  const durationsRealistic = validateEncounterDurations(encounters, warnings);

  // Type validation
  const typesValid = validateEncounterTypes(encounters, warnings);

  // Temporal consistency
  const temporalConsistent = validateEncounterTemporal(encounters, warnings);

  // Overlap detection
  const overlapsDetected = detectEncounterOverlaps(encounters, warnings);

  // Participant validation
  const participantsValid = validateEncounterParticipants(encounters, warnings);

  const result: EncounterValidationResult = {
    durationsRealistic,
    typesValid,
    temporalConsistent,
    overlapsDetected,
    participantsValid,
  };

  return { errors, warnings, result };
}

/**
 * Validate condition resources
 */
function validateConditions(conditions: Condition[]) {
  const errors: string[] = [];
  const warnings: string[] = [];

  const statusesValid = true; // Basic status validation
  const onsetConsistent = true; // Onset date validation
  const severityAppropriate = true; // Severity assessment
  const evidenceLinked = true; // Evidence link validation

  const result: ConditionValidationResult = {
    statusesValid,
    onsetConsistent,
    severityAppropriate,
    evidenceLinked,
  };

  return { errors, warnings, result };
}

/**
 * Cross-resource validation
 */
function validateCrossResource(bundle: Bundle, resources: {
  patient?: Patient;
  observations: Observation[];
  encounters: Encounter[];
  conditions: Condition[];
}) {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Reference integrity validation (should be 100% in this dataset)
  const referenceIntegrity = validateReferenceIntegrity(bundle, errors);

  // Temporal consistency (birth date vs observations)
  const temporalConsistency = validateTemporalConsistency(resources, warnings);

  // Clinical logic validation
  const clinicalLogic = validateClinicalLogic(resources, warnings);

  // Duplicate detection
  const duplicatesDetected = detectDuplicates(resources, warnings);

  const result: CrossResourceValidationResult = {
    referenceIntegrity,
    temporalConsistency,
    clinicalLogic,
    duplicatesDetected,
  };

  return { errors, warnings, result };
}

// Helper validation functions
function validatePatientNames(patient: Patient, warnings: string[]): boolean {
  if (!patient.name || patient.name.length === 0) {
    warnings.push('Patient has no name');
    return false;
  }
  // Allow flexible naming patterns for international names
  return true;
}

function validatePatientIdentifiers(patient: Patient, warnings: string[]): boolean {
  const expectedTypes = ['SSN', 'MRN', 'DL', 'PP'];
  const presentTypes = patient.identifier?.map(id => id.type?.text) || [];
  const missingTypes = expectedTypes.filter(type => !presentTypes.includes(type));

  if (missingTypes.length > 0) {
    warnings.push(`Patient missing identifier types: ${missingTypes.join(', ')}`);
  }

  return missingTypes.length === 0;
}

function validatePatientDemographics(patient: Patient, errors: string[]): boolean {
  if (!patient.gender) {
    errors.push('Patient missing gender');
    return false;
  }
  if (!patient.birthDate) {
    errors.push('Patient missing birth date');
    return false;
  }
  return true;
}

function validatePatientContact(patient: Patient, warnings: string[]): boolean {
  const phoneFormat = /^\d{3}-\d{3}-\d{4}$/;
  const phoneNumbers = patient.telecom?.filter(t => t.system === 'phone') || [];

  for (const phone of phoneNumbers) {
    if (phone.value && !phoneFormat.test(phone.value)) {
      warnings.push(`Invalid phone format: ${phone.value}`);
      return false;
    }
  }
  return true;
}

function validatePatientGeography(patient: Patient, warnings: string[]): boolean {
  const addresses = patient.address || [];
  const nonMAAddresses = addresses.filter(addr => addr.state !== 'MA');

  if (nonMAAddresses.length > 0) {
    warnings.push('Patient has non-Massachusetts address (unexpected for this dataset)');
    return false;
  }
  return true;
}

function validateObservationValues(observations: Observation[], warnings: string[]): boolean {
  // Handle scientific notation in units (e.g., "10*3/uL" = 10³/uL)
  for (const obs of observations) {
    if (obs.valueQuantity?.value !== undefined && obs.valueQuantity?.unit) {
      const unit = obs.valueQuantity.unit;
      if (unit.includes('*')) {
        // Scientific notation detected - don't flag as abnormal
        continue;
      }
      // Add specific range validations based on observation type
    }
  }
  return true;
}

function validateObservationUnits(observations: Observation[], warnings: string[]): boolean {
  const unitInconsistencies: string[] = [];

  // Group by observation type and check unit consistency
  const observationsByType = new Map<string, Observation[]>();
  for (const obs of observations) {
    const code = obs.code?.text || 'Unknown';
    if (!observationsByType.has(code)) {
      observationsByType.set(code, []);
    }
    observationsByType.get(code)!.push(obs);
  }

  for (const [type, typeObs] of observationsByType) {
    const units = new Set(typeObs.map(o => o.valueQuantity?.unit).filter(Boolean));
    if (units.size > 1) {
      unitInconsistencies.push(`${type}: ${Array.from(units).join(', ')}`);
    }
  }

  if (unitInconsistencies.length > 0) {
    warnings.push(`Unit inconsistencies found: ${unitInconsistencies.join('; ')}`);
  }

  return unitInconsistencies.length === 0;
}

function validateObservationReferences(observations: Observation[], errors: string[]): boolean {
  for (const obs of observations) {
    if (!obs.subject?.reference) {
      errors.push('Observation missing patient reference');
      return false;
    }
    if (!obs.encounter?.reference && obs.encounter !== undefined) {
      errors.push('Observation has invalid encounter reference');
      return false;
    }
  }
  return true;
}

function validateObservationTemporal(observations: Observation[], warnings: string[]): boolean {
  // Check for same-time observations (potential synthetic data artifact)
  const timeMap = new Map<string, number>();
  for (const obs of observations) {
    if (obs.effectiveDateTime) {
      const count = timeMap.get(obs.effectiveDateTime) || 0;
      timeMap.set(obs.effectiveDateTime, count + 1);
    }
  }

  const duplicateTimes = Array.from(timeMap.entries()).filter(([, count]) => count > 1);
  if (duplicateTimes.length > 0) {
    warnings.push(`${duplicateTimes.length} exact-time duplicates found (synthetic data artifact)`);
  }

  return true;
}

function validateEncounterDurations(encounters: Encounter[], warnings: string[]): boolean {
  const longEncounters = encounters.filter(enc => {
    if (!enc.period?.start || !enc.period?.end) return false;
    const duration = new Date(enc.period.end).getTime() - new Date(enc.period.start).getTime();
    const hours = duration / (1000 * 60 * 60);
    return hours > 24;
  });

  if (longEncounters.length > 0) {
    warnings.push(`${longEncounters.length} encounters longer than 24 hours (may be legitimate for hospice/rehab)`);
  }

  return true;
}

function validateEncounterTypes(encounters: Encounter[], warnings: string[]): boolean {
