function detectEncounterOverlaps(encounters: Encounter[], warnings: string[]): boolean {
  const overlaps: string[] = [];

  for (let i = 0; i < encounters.length; i++) {
    for (let j = i + 1; j < encounters.length; j++) {
      const enc1 = encounters[i];
      const enc2 = encounters[j];

      if (!enc1.period?.start || !enc1.period?.end || !enc2.period?.start || !enc2.period?.end) {
        continue;
      }

      const start1 = new Date(enc1.period.start);
      const end1 = new Date(enc1.period.end);
      const start2 = new Date(enc2.period.start);
      const end2 = new Date(enc2.period.end);

      if ((start1 <= end2 && end1 >= start2)) {
        overlaps.push(`${enc1.id} overlaps with ${enc2.id}`);
      }
    }
  }

  if (overlaps.length > 0) {
    warnings.push(`Encounter overlaps detected: ${overlaps.length} overlaps`);
  }

  return overlaps.length === 0;
}

function validateEncounterParticipants(encounters: Encounter[], warnings: string[]): boolean {
