function validateReferenceIntegrity(bundle: Bundle, errors: string[]): boolean {
  const resourceIds = new Set(bundle.entry?.map(e => `urn:uuid:${e.resource?.id}`));
  let allReferencesValid = true;

  for (const entry of bundle.entry || []) {
    const resource = entry.resource;
    if (!resource) continue;

    // Check common reference fields
    const references: string[] = [];
    if ('subject' in resource && resource.subject?.reference) {
      references.push(resource.subject.reference);
    }
    if ('encounter' in resource && resource.encounter?.reference) {
      references.push(resource.encounter.reference);
    }

    for (const ref of references) {
      if (!resourceIds.has(ref)) {
        errors.push(`Broken reference: ${ref} in ${resource.resourceType}/${resource.id}`);
        allReferencesValid = false;
      }
    }
  }

  return allReferencesValid;
}

function validateTemporalConsistency(resources: {
  patient?: Patient;
  observations: Observation[];
  encounters: Encounter[];
  conditions: Condition[];
}, warnings: string[]): boolean {
  if (!resources.patient?.birthDate) return true;

  const birthDate = new Date(resources.patient.birthDate);
  let beforeBirthCount = 0;

  for (const obs of resources.observations) {
    if (obs.effectiveDateTime) {
      const obsDate = new Date(obs.effectiveDateTime);
      if (obsDate < birthDate) {
        beforeBirthCount++;
      }
    }
  }

  if (beforeBirthCount > 0) {
    warnings.push(`${beforeBirthCount} observations appear before birth date (likely same-day timing issue)`);
  }

  return true;
}

