function calculateQualityScore(errors: string[], warnings: string[], bundle: Bundle): number {
  let score = 100;

  // Deduct points for errors and warnings
  score -= errors.length * 10;
  score -= warnings.length * 2;

  // Bonus for completeness
  const entryCount = bundle.entry?.length || 0;
  if (entryCount > 100) score += 5;
  if (entryCount > 1000) score += 5;

  return Math.max(0, Math.min(100, score));
}

/**
 * Validate multiple bundles and provide aggregate validation results
 */
export function validateMultipleBundles(loadResults: LoadResult[]): {
  overallValid: boolean;
  successfulValidations: number;
  failedValidations: number;
  commonErrors: Record<string, number>;
  commonWarnings: Record<string, number>;
  averageQualityScore: number;
  validationResults: ValidationResult[];
} {
  const validationResults = loadResults
    .filter(r => r.success && r.bundle)
    .map(r => validateBundle(r.bundle!));

  const successfulValidations = validationResults.filter(v => v.isValid).length;
  const failedValidations = validationResults.length - successfulValidations;

  // Aggregate common errors and warnings
  const commonErrors: Record<string, number> = {};
  const commonWarnings: Record<string, number> = {};

  for (const result of validationResults) {
    for (const error of result.errors) {
      commonErrors[error] = (commonErrors[error] || 0) + 1;
    }
    for (const warning of result.warnings) {
      commonWarnings[warning] = (commonWarnings[warning] || 0) + 1;
    }
  }

  const averageQualityScore = validationResults.reduce((sum, r) => sum + r.qualityScore, 0) / validationResults.length;

  return {
    overallValid: failedValidations === 0,
    successfulValidations,
    failedValidations,
    commonErrors,
    commonWarnings,
    averageQualityScore,
    validationResults,
  };
}

/**
 * Healthcare EHR Data Loader
 * 
 * A comprehensive data loading system for the Synthea-generated healthcare dataset.
 * Provides schemas, validation, and utilities for working with FHIR healthcare data.
 * 
 * DATASET CHARACTERISTICS:
 * - 708 synthetic patients with complete medical histories
 * - FHIR R4 format with US Core profiles
 * - ~5.3 million total medical records
 * - File sizes: 0.1MB to 54.7MB per patient
 * - Geographic scope: Massachusetts, USA
 * - Date range: 1973-2025 (synthetic data)
 * 
 * USAGE:
 * ```typescript
 * import { loadFhirBundle, validateBundle, analyzeFhirDirectory } from './index';
 * 
 * // Load a single patient file
 * const result = loadFhirBundle('/path/to/patient.json');
 * 
 * // Validate the data
 * const validation = validateBundle(result.bundle);
 * 
 * // Analyze a directory of files
 * const analysis = analyzeFhirDirectory('/path/to/fhir/directory');
 * ```
 */

// Re-export all schemas and types
export * from './schemas';

// Re-export loader functionality
export {
  loadFhirBundle,
  loadFhirBundles,
  analyzeFhirDirectory,
  getSampleBundles,
  type LoadResult,
  type LoadOptions,
} from './loaders/fhir-loader';

// Re-export validation functionality
export {
  validateBundle,
  validateMultipleBundles,
  type ValidationResult,
  type PatientValidationResult,
  type ObservationValidationResult,
  type EncounterValidationResult,
  type ConditionValidationResult,
  type CrossResourceValidationResult,
} from './validations/comprehensive-validation';

// Utility functions for common use cases
import { loadFhirBundles, analyzeFhirDirectory } from './loaders/fhir-loader';
import { validateBundle } from './validations/comprehensive-validation';
import { extractBundleSummary, getResourcesByType } from './schemas';

/**
 * Quick data quality assessment of a directory
 */
export function quickQualityAssessment(directoryPath: string, sampleSize: number = 20) {
  const analysis = analyzeFhirDirectory(directoryPath, sampleSize);

  const loadResults = loadFhirBundles(directoryPath, { limit: sampleSize });
  const validationResults = loadResults
    .filter(r => r.success && r.bundle)
    .map(r => validateBundle(r.bundle!));

  const qualityScores = validationResults.map(v => v.qualityScore);
  const avgQualityScore = qualityScores.reduce((sum, score) => sum + score, 0) / qualityScores.length;

  return {
    ...analysis,
    dataQuality: {
      averageQualityScore: avgQualityScore,
      highQualityFiles: qualityScores.filter(s => s >= 90).length,
      mediumQualityFiles: qualityScores.filter(s => s >= 70 && s < 90).length,
      lowQualityFiles: qualityScores.filter(s => s < 70).length,
      validationResults: validationResults.slice(0, 5), // First 5 for review
    }
  };
}

/**
 * Extract structured data from a loaded bundle
 */
export function extractStructuredData(bundle: any) {
  const summary = extractBundleSummary(bundle);

  return {
    patient: getResourcesByType(bundle, 'Patient')[0],
    observations: getResourcesByType(bundle, 'Observation'),
    encounters: getResourcesByType(bundle, 'Encounter'),
    conditions: getResourcesByType(bundle, 'Condition'),
    diagnosticReports: getResourcesByType(bundle, 'DiagnosticReport'),
    medications: getResourcesByType(bundle, 'MedicationRequest'),
    procedures: getResourcesByType(bundle, 'Procedure'),
    claims: getResourcesByType(bundle, 'Claim'),
    explanationOfBenefits: getResourcesByType(bundle, 'ExplanationOfBenefit'),
    summary,
  };
}

/**
 * Validate and load data with comprehensive error handling
 */
export function safeLoadAndValidate(filePath: string) {
  try {
    const loadResult = loadFhirBundles(filePath)[0];

    if (!loadResult.success) {
      return {
        success: false,
        error: 'Failed to load file',
        details: loadResult.errors,
      };
    }

    if (!loadResult.bundle) {
      return {
        success: false,
        error: 'No bundle data found',
        details: [],
      };
    }

    const validation = validateBundle(loadResult.bundle);
    const structuredData = extractStructuredData(loadResult.bundle);

    return {
      success: true,
      loadResult,
      validation,
      data: structuredData,
    };

  } catch (error: any) {
    return {
      success: false,
      error: error.message,
      details: [error.stack || 'No stack trace available'],
    };
  }
}

/**
 * Get dataset overview and statistics
 */
export function getDatasetOverview(directoryPath: string) {
  const analysis = analyzeFhirDirectory(directoryPath, 50);

  return {
    totalFiles: analysis.summary.totalFiles,
    avgFileSize: `${analysis.summary.avgSizeMBPerFile.toFixed(1)} MB`,
    avgRecordsPerFile: Math.round(analysis.summary.avgEntriesPerFile),
    totalRecords: analysis.summary.totalEntries,
    estimatedTotalRecords: Math.round((analysis.summary.totalEntries / analysis.summary.totalFiles) * 708), // Extrapolate to full dataset

    resourceDistribution: Object.entries(analysis.resourceTypeDistribution)
      .slice(0, 10)
      .map(([type, stats]) => ({
        resourceType: type,
        count: stats.count,
        percentage: `${stats.percentage.toFixed(1)}%`,
      })),

    fileSize: {
      smallest: `${analysis.distributionStats.fileSizes.min} MB`,
      median: `${analysis.distributionStats.fileSizes.median} MB`,
      largest: `${analysis.distributionStats.fileSizes.max} MB`,
    },

    complexityRange: {
      simplest: `${analysis.distributionStats.entryCounts.min} records`,
      median: `${analysis.distributionStats.entryCounts.median} records`,
      mostComplex: `${analysis.distributionStats.entryCounts.max} records`,
    },

    qualityIndicators: {
      loadSuccessRate: `${((analysis.summary.successfulLoads / analysis.summary.totalFiles) * 100).toFixed(1)}%`,
      commonErrors: Object.keys(analysis.errors).length,
      commonWarnings: Object.keys(analysis.warnings).length,
    },

    patientDemographics: {
      sampleSize: analysis.patientSummaries.length,
      genderDistribution: analysis.patientSummaries.reduce((acc: any, p: any) => {
        acc[p.gender] = (acc[p.gender] || 0) + 1;
        return acc;
      }, {}),
    },
  };
}

// Default data directory path (can be overridden)
export const DEFAULT_DATA_PATH = '../data/fhir';

/**
 * Convenience function to get started quickly
 */
export function quickStart(dataPath: string = DEFAULT_DATA_PATH) {
  console.log('🏥 Healthcare EHR Data Loader - Quick Start');
  console.log('============================================');

