    console.log(`\n📋 Top Resource Types:`);
    overview.resourceDistribution.slice(0, 5).forEach(r => {
      console.log(`   • ${r.resourceType}: ${r.count.toLocaleString()} (${r.percentage})`);
    });

    console.log(`\n✅ Data loader is ready!`);
    console.log(`\nExample usage:`);
    console.log(`   import { loadFhirBundle } from './index';`);
    console.log(`   const result = loadFhirBundle('${dataPath}/patient-file.json');`);

    return overview;

  } catch (error: any) {
