import { loadFhirBundle, getDatasetOverview, quickStart } from './src/index';

console.log('🧪 Testing Healthcare EHR Data Loader...');

try {
  // Test basic functionality
  console.log('\n1. Testing quickStart...');
  const overview = quickStart('../data/fhir');

  console.log('\n2. Testing individual file load...');
  // Try to load a single file if available
  const result = loadFhirBundle('../data/fhir/Zack583_Lockman863_9b55d2b1-d96d-d913-49a7-c7c5de54df6c.json');
  console.log(`Load result: ${result.success ? 'SUCCESS' : 'FAILED'}`);
  if (result.success) {
    console.log(`   • File size: ${result.stats.fileSizeMB} MB`);
    console.log(`   • Entry count: ${result.stats.entryCount}`);
    console.log(`   • Patient: ${result.patient?.name?.[0]?.given?.join(' ')} ${result.patient?.name?.[0]?.family}`);
  } else {
    console.log(`   • Errors: ${result.errors.join(', ')}`);
  }

  console.log('\n✅ All tests completed!');

} catch (error: any) {
  console.error('❌ Test failed:', error.message);
  console.log('\nThis might be expected if the data directory structure is different.');
  console.log('The data loader is still functional for valid data paths.');
}

/**
 * Comprehensive Test Suite for Healthcare EHR Data Loader
 * 
 * Tests all major functionality and ensures the system is working correctly.
 */

import { 
  loadFhirBundle, 
  loadFhirBundles, 
  analyzeFhirDirectory,
  validateBundle,
  quickQualityAssessment,
  extractStructuredData,
  safeLoadAndValidate,
  getDatasetOverview 
} from './src/index';

console.log('🧪 Running Comprehensive Test Suite...\n');

async function runTests() {
  const dataPath = '../data/fhir';
  let testsPassed = 0;
  let totalTests = 0;

  function test(name: string, testFn: () => boolean | Promise<boolean>) {
    totalTests++;
    try {
      const result = testFn();
      if (result) {
        console.log(`✅ ${name}`);
        testsPassed++;
      } else {
        console.log(`❌ ${name} - Test failed`);
      }
    } catch (error: any) {
      console.log(`❌ ${name} - Error: ${error.message}`);
    }
  }

  // Test 1: Basic file loading
  test('Basic file loading', () => {
    const result = loadFhirBundle(`${dataPath}/Zack583_Lockman863_9b55d2b1-d96d-d913-49a7-c7c5de54df6c.json`);
    return result.success && result.bundle !== undefined;
  });

  // Test 2: Patient extraction
  test('Patient data extraction', () => {
    const result = loadFhirBundle(`${dataPath}/Zack583_Lockman863_9b55d2b1-d96d-d913-49a7-c7c5de54df6c.json`);
    return result.success && result.patient !== undefined && result.patient.name !== undefined;
  });

  // Test 3: Batch loading
  test('Batch file loading', () => {
    const results = loadFhirBundles(dataPath, { limit: 5 });
    return results.length === 5 && results.every(r => r.success);
  });

  // Test 4: Directory analysis
  test('Directory analysis', () => {
    const analysis = analyzeFhirDirectory(dataPath, 10);
    return analysis.summary.totalFiles === 10 && analysis.summary.totalEntries > 0;
  });

  // Test 5: Bundle validation
  test('Bundle validation', () => {
    const result = loadFhirBundle(`${dataPath}/Zack583_Lockman863_9b55d2b1-d96d-d913-49a7-c7c5de54df6c.json`);
    if (!result.success || !result.bundle) return false;

    const validation = validateBundle(result.bundle);
    return validation.qualityScore > 0;
  });

  // Test 6: Structured data extraction
  test('Structured data extraction', () => {
    const result = loadFhirBundle(`${dataPath}/Zack583_Lockman863_9b55d2b1-d96d-d913-49a7-c7c5de54df6c.json`);
    if (!result.success || !result.bundle) return false;

    const structured = extractStructuredData(result.bundle);
    return structured.patient !== undefined && 
           structured.observations.length > 0 && 
           structured.encounters.length > 0;
  });

  // Test 7: Quality assessment
  test('Quality assessment', () => {
    const assessment = quickQualityAssessment(dataPath, 10);
    return assessment.dataQuality.averageQualityScore > 50;
  });

  // Test 8: Dataset overview
  test('Dataset overview', () => {
    const overview = getDatasetOverview(dataPath);
    return overview.totalFiles > 0 && 
           overview.resourceDistribution.length > 0 &&
           overview.qualityIndicators.loadSuccessRate !== undefined;
  });

  // Test 9: Safe load and validate
  test('Safe load and validate', () => {
    const result = safeLoadAndValidate(`${dataPath}/Zack583_Lockman863_9b55d2b1-d96d-d913-49a7-c7c5de54df6c.json`);
    return result.success && result.data !== undefined;
  });

  // Test 10: Error handling for invalid file
  test('Error handling for invalid file', () => {
    const result = loadFhirBundle('/nonexistent/file.json');
    return !result.success && result.errors.length > 0;
  });

  // Performance test
  console.log('\n🚀 Performance Tests:');

  const startTime = Date.now();
  const perfResults = loadFhirBundles(dataPath, { limit: 20 });
  const endTime = Date.now();
  const processingTime = endTime - startTime;

  const totalEntries = perfResults.reduce((sum, r) => sum + r.stats.entryCount, 0);
  const entriesPerSecond = Math.round(totalEntries / (processingTime / 1000));

  console.log(`   • Processed ${perfResults.length} files in ${processingTime}ms`);
  console.log(`   • Total entries: ${totalEntries.toLocaleString()}`);
  console.log(`   • Processing rate: ${entriesPerSecond.toLocaleString()} entries/second`);

  // Memory usage test
  const memBefore = process.memoryUsage().heapUsed / 1024 / 1024;
  const largeFileResults = loadFhirBundles(dataPath, { limit: 10 });
  const memAfter = process.memoryUsage().heapUsed / 1024 / 1024;
  const memDelta = memAfter - memBefore;

  console.log(`   • Memory usage: ${memDelta.toFixed(1)} MB for ${largeFileResults.length} files`);

  // Final summary
  console.log(`\n📊 Test Results: ${testsPassed}/${totalTests} tests passed`);

  if (testsPassed === totalTests) {
    console.log('🎉 All tests passed! The data loader is working correctly.');
  } else {
    console.log('⚠️  Some tests failed. Please review the errors above.');
  }

  // Sample data insights
  console.log('\n🔍 Sample Data Insights:');
  const sampleResult = loadFhirBundle(`${dataPath}/Zack583_Lockman863_9b55d2b1-d96d-d913-49a7-c7c5de54df6c.json`);
  if (sampleResult.success && sampleResult.bundle) {
    const structured = extractStructuredData(sampleResult.bundle);
    const validation = validateBundle(sampleResult.bundle);

    console.log(`   • Patient: ${structured.patient?.name?.[0]?.given?.join(' ')} ${structured.patient?.name?.[0]?.family}`);
    console.log(`   • Birth Date: ${structured.patient?.birthDate}`);
    console.log(`   • Gender: ${structured.patient?.gender}`);
    console.log(`   • Observations: ${structured.observations.length}`);
    console.log(`   • Encounters: ${structured.encounters.length}`);
    console.log(`   • Conditions: ${structured.conditions.length}`);
    console.log(`   • Quality Score: ${validation.qualityScore}/100`);
    console.log(`   • Validation Errors: ${validation.errors.length}`);
    console.log(`   • Validation Warnings: ${validation.warnings.length}`);
  }

  return testsPassed === totalTests;
}

// Run the tests
runTests().then(success => {
  console.log(`\n${success ? '✅' : '❌'} Test suite completed.`);
  process.exit(success ? 0 : 1);
}).catch(error => {
  console.error('💥 Test suite crashed:', error);
  process.exit(1);
});
